   "id": "M1:T6",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "It is the first thing a user must do to begin using KeePass.",
     "role": "statement"
    },
    {
     "text": "Its main function is the determination of the master password that will unlock the database from now on",
     "role": "statement"
    }
